 template <class T>
 static void _copy_loop(Vector &left, void *target, size_t element_count,
                        size_t offset) {
 	T *ldata = (T *)left.data;
 	T *result_data = (T *)target;
 	if (left.sel_vector) {
 		for (size_t i = offset; i < offset + element_count; i++) {
 			result_data[i] = ldata[left.sel_vector[i]];
 		}
 	} else {
 		for (size_t i = offset; i < offset + element_count; i++) {
 			result_data[i] = ldata[i];
 		}
 	}
