 template <class T> int full_scan(T *keys, idx_t size, T low, T high) {
 	int sum = 0;
 	for (idx_t i = 0; i < size; i++) {
 		if (keys[i] >= low && keys[i] <= high) {
 			sum += 1;
 		}
 	}
 	return sum;
 }

