 	index_t read_count = source.eof() ? source.gcount() : buffer_read_size;
 	buffer_size = remaining + read_count;
 	buffer[buffer_size] = '\0';
 	if (old_buffer && start != 0) {
 		cached_buffers.push_back(move(old_buffer));
 	}
 	start = 0;
 	position = remaining;

