+template <class T, bool SAFE = true>
+class atomic_ptr { // NOLINT: mimic std casing
+public:
+	atomic_ptr() noexcept : ptr(nullptr) {
+	}
+	atomic_ptr(T *ptr_p) : ptr(ptr_p) { // NOLINT: allow implicit creation from pointer
+	}
