uint32_t EncodeFloat(float x)
{
    int shift;
    unsigned long sign, exp, hibits, buff;
    double fnorm, significand;
    int expbits = 8;
    int significandbits = 23;

    //! zero (can't handle signed zero)
    if (x == 0)
    {
        buff = 0;
        return buff;
    }
    //! infinity
    if (x > FLT_MAX)
    {
        buff = 128 + ((1 << (expbits - 1)) - 1);
        buff <<= (31 - expbits);
        return buff;
    }
