 	Mult = Multiplier;
 	Z = (DSS_HUGE)*StartSeed;
 	while (N > 0) {
 		if (N % 2 != 0) /* testing for oddness, this seems portable */
 			Z = (Mult * Z) % Modulus;
 		N = N / 2; /* integer division, truncates */
 		Mult = (Mult * Mult) % Modulus;
 	}
 	*StartSeed = Z;

 	return;
 }

