 		for (auto &index : storage->indexes) {
 			if (!index->Append(chunk, row_ids)) {
 				throw ConstraintException("PRIMARY KEY or UNIQUE constraint violated: duplicated key");
 			}
 		}
 	}

 	//! Append to the chunk
 	storage->collection.Append(chunk);


