 //===--------------------------------------------------------------------===//
 // Divide
 //===--------------------------------------------------------------------===//
 static uint8_t Bits(uhugeint_t x) {
 	uint8_t out = 0;
 	if (x.upper) {
 		out = 64;
 		for (uint64_t upper = x.upper; upper; upper >>= 1) {
 			++out;
 		}
 	} else {
 		for (uint64_t lower = x.lower; lower; lower >>= 1) {
 			++out;
 		}
 	}
 	return out;
 }

