+			break;
 		case TypeId::POINTER:
 			TemplatedExecute<uintptr_t, OP>(left, right, result, count);
 			break;
 		case TypeId::FLOAT:
 			TemplatedExecute<float, OP>(left, right, result, count);
 			break;
 		case TypeId::DOUBLE:
 			TemplatedExecute<double, OP>(left, right, result, count);
 			break;
 		case TypeId::INTERVAL:
