+	}
+	if (StringUtil::Equals(type, "catalog")) {
+		return CompletionType::CATALOG_NAME;
+	}
+	if (StringUtil::Equals(type, "schema")) {
+		return CompletionType::SCHEMA_NAME;
+	}
+	if (StringUtil::Equals(type, "table")) {
