bool Pipeline::IsOrderDependent() const {
	auto &config = DBConfig::GetConfig(executor.context);
	if (!config.preserve_insertion_order) {
		return false;
	}
	if (sink->IsOrderDependent() || source->IsOrderDependent()) {
		return true;
	}
	for (auto &op : operators) {
