+uint32_t FixedSizeAllocator::GetOffset(ValidityMask &mask, const idx_t segment_count) {
+
+	auto data = mask.GetData();
+
+	// fills up a buffer sequentially before searching for free bits
+	if (mask.RowIsValid(segment_count)) {
