 		evicted_data_per_tag[uint8_t(tag)] -= GetBlockSize();
 		return temporary_directory.handle->GetTempFile().ReadTemporaryBuffer(id, std::move(reusable_buffer));
 	}

 	// Open the temporary file and read its size.
 	idx_t block_size;
