+	auto string_data = allocated_string.GetDataWriteable();
+	uint32_t copied_count = 0;
+	bool escaped = false;
+
+	bool quoted = false;
+	char quote_char;
+	stack<char> scopes;
+	for (idx_t i = 0; i < length; i++) {
+		auto current_char = buf[start + i];
+		if (!escaped) {
+			if (scopes.empty() && current_char == '\\') {
