+				escaped = true;
+				continue;
+			}
+			if (scopes.empty() && (current_char == '\'' || current_char == '"')) {
+				if (quoted && current_char == quote_char) {
+					quoted = false;
+					//! Skip the ending quote
+					continue;
+				} else if (!quoted) {
+					quoted = true;
+					quote_char = current_char;
+					//! Skip the starting quote
+					continue;
