+	Vector::RecursiveToUnifiedFormat(input, count, recursive_format);
+	UnifiedVariantVectorData variant(recursive_format);
+
+	for (idx_t i = 0; i < count; i++) {
+		AnalyzeSchemaInternal(state.analyze_data, variant, i, 0);
+	}
+}
